\section*{Claim}
In the internal-color model of a fundamental \(SU(N_c)\) flux tube, if \(F\) is the number of crossings of the spatial boundary between \(V\) and \(\overline{V}\), then the internal contribution is
\[
S_{\rm internal}=\langle F\rangle\log N_c.
\]
When \(F\) is deterministic, as in a one-spatial-dimensional flux tube crossing a fixed number of boundaries, this reduces to \(\widetilde S^{(q)}_{|Q\bar Q}=F\log N_c\).

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & N_c\in\mathbb{Z},\quad N_c\geq 2.\\[1mm]
\text{(P2)} & \text{One fundamental-representation boundary crossing contributes }\log N_c\text{ to internal entropy}.\\[1mm]
\text{(P3)} & \text{If a configuration has }F\in\{0,1,2,\ldots\}\text{ crossings, then }S_{\rm internal}(F):=F\log N_c.\\[1mm]
\text{(P4)} & \Pr(F=f)=P_f,\\quad P_f\geq 0,\quad \displaystyle\sum_{f=0}^{\infty}P_f=1.\\[2mm]
\text{(P5)} & \displaystyle \langle F\rangle:=\sum_{f=0}^{\infty}fP_f.\\[2mm]
\text{(P6)} & \text{If }F=F_0\text{ deterministically, then }P_f=\begin{cases}1,& f=F_0,\\0,& f\neq F_0.\end{cases}
\end{array}
\]

\section*{Derivation}
\begin{align}
S_{\rm internal}
&:=\sum_{f=0}^{\infty}P_fS_{\rm internal}(f) && \text{definition of average internal entropy}\\
&=\sum_{f=0}^{\infty}P_f(f\log N_c) && \text{by (P3)}\\
&=\left(\sum_{f=0}^{\infty}fP_f\right)\log N_c && \text{factor out constant }\log N_c\\
&=\langle F\rangle\log N_c && \text{by (P5)}.
\end{align}
For deterministic \(F=F_0\),
\begin{align}
\langle F\rangle
&=\sum_{f=0}^{\infty}fP_f && \text{by (P5)}\\
&=F_0\cdot 1+\sum_{f\neq F_0}f\cdot 0 && \text{by (P6)}\\
&=F_0,\\
S_{\rm internal}
&=F_0\log N_c && \text{substitute into the average formula}.
\end{align}

\section*{Final Result}
\[
\boxed{\displaystyle S_{\rm internal}=\langle F\rangle\log N_c,\qquad F=F_0\Rightarrow \widetilde S^{(q)}_{|Q\bar Q}=F_0\log N_c}
\]
\hfill$\blacksquare$
